<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
$event=(int)($_GET['event_id']??0);$status=$_GET['status']??'En revisión';$search=trim($_GET['search']??'');$args=[];$where=['r.created_by IS NULL'];if($event){$where[]='r.event_id=?';$args[]=$event;}if($status!==''){if($status==='En revisión')$where[]="(EXISTS(SELECT 1 FROM pagos_inscripcion pa WHERE pa.estado_abono='En revisión' AND pa.codigo_conjunto COLLATE utf8mb4_unicode_ci=IF(r.codigo_grupo IS NULL,CONCAT('persona-',r.id),CONCAT('grupo-',r.codigo_grupo))) OR r.status='En revisión')";else{$where[]='r.status=?';$args[]=$status;}}if($search!==''){$where[]='(CONCAT(r.first_name,\' \',r.last_name) LIKE ? OR r.ci LIKE ?)';array_push($args,'%'.$search.'%','%'.$search.'%');}
$page=max(1,(int)($_GET['page']??1));$count=(int)q('SELECT COUNT(*) FROM registrations r WHERE '.implode(' AND ',$where),$args)->fetchColumn();$rows=all('SELECT r.*,e.name event_name FROM registrations r JOIN events e ON e.id=r.event_id WHERE '.implode(' AND ',$where).' ORDER BY r.id DESC LIMIT 50 OFFSET '.(($page-1)*50),$args);headerPage('Verificar y confirmar inscripciones en línea'); ?>
<div class="alert alert-warning">Adjuntar un comprobante no confirma la inscripción. Compare el importe, referencia, fecha y cuenta receptora con su movimiento bancario; después abra la ficha y confirme o rechace. El sistema no verifica movimientos del banco automáticamente.</div>
<div class="card p-4"><form method="get"><input type="hidden" name="p" value="online"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$event);?></div><div class="col-md-4"><?php selectField('status','Estado',[''=>'Todos','En revisión'=>'Comprobante para verificar','Pendiente'=>'Sin comprobante','Pagado'=>'Inscripción confirmada','Rechazado'=>'Comprobante rechazado','Anulado'=>'Inscripción anulada'],$status);?></div><div class="col-md-4"><?php field('search','Nombre / CI',$search,'text',false);?></div></div><button class="btn btn-primary">Filtrar inscritos en línea</button></form></div>
<div class="card p-3"><p><?=e($count)?> inscripciones encontradas</p><div class="table-responsive"><table class="table table-striped"><tr><th>Registro</th><th>Participante</th><th>Evento</th><th>Importe esperado</th><th>Referencia enviada</th><th>Estado</th><th>Comprobante</th><th>Acción</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['id'])?> · <?=e($r['created_at'])?></td><td><?=e(nombreParticipante($r))?><br>CI <?=e($r['ci'])?></td><td><?=e($r['event_name'])?></td><td><?=money($r['price'])?><br><small>Verificado <?=money($r['monto_cobrado'])?> · Debe <?=money(max(0,$r['price']-$r['monto_cobrado']))?></small><?php if($r['codigo_grupo']):$personasGrupo=integrantesGrupo($r);?><br><small>Grupo de <?=count($personasGrupo)?> · Total <?=money(array_sum(array_column($personasGrupo,'price')))?></small><?php endif?></td><td><?=e($r['reference'])?></td><td><?=e($r['status'])?></td><td><?php if($r['proof']):?><a class="btn btn-sm btn-outline-primary" href="<?=fileUrl($r['proof'])?>" target="_blank" rel="noopener">Abrir comprobante</a><?php else:?>Sin adjunto<?php endif?></td><td><a class="btn btn-sm btn-primary" href="<?=url('p=participant&t='.$r['token'])?>">Verificar / confirmar</a></td></tr><?php endforeach?></table></div><div><?php if($page>1):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">Anterior</a><?php endif?> Página <?=e($page)?><?php if($page*50<$count):?> <a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Siguiente</a><?php endif?></div></div>
<?php footerPage();
